style.css:
@-moz-document domain("roblox.com") {
/* ===== FONDO GLOBAL REAL ===== */
    html, body {
        background: transparent !important;
    }

    #container-main,
    .container-main,
    .content,
    .rbx-body,
    #rbx-body,
    #navigation-container {
        background-image: url("https://i.imgur.com/M1eorlV.jpeg") !important;
        background-size: cover !important;
        background-position: center top !important;
        background-attachment: fixed !important;
        background-repeat: no-repeat !important;
    }

    /* Capa oscura ENCIMA del fondo */
    #container-main::before {
        content: "";
        position: fixed;
        inset: 0;
        background: rgba(11, 18, 24, 0.55);
        pointer-events: none;
        z-index: 0;
    }

    /* Elevar el contenido */
    #container-main > * {
        position: relative;
        z-index: 1;
    }

    /* ===== TARJETAS ===== */
    .card,
    .rbx-panel,
    .section-content {
        background: rgba(15, 42, 61, 0.65) !important;
        backdrop-filter: blur(6px);
        border-radius: 14px;
        border: 1px solid rgba(79, 195, 199, 0.25);
    }

    /* ===== TEXTO ===== */
    * {
        color: #F2F4F8 !important;
    }

    a {
        color: #7FDBE0 !important;
    }

    a:hover {
        color: #4FC3C7 !important;
    }
}
